Módulo 3. Disección Práctica del Código Real (4-mattasur-analysis-technical.qmd)
A continuación revisamos paso a paso los bloques de código reales con los que se construyó el diagnóstico del Gran Matta Sur y la Comuna de Santiago, ejecutando una demostración en vivo directamente en este documento.

Paso 1. Carga de Paquetes, Barrios y Disolución en las 4 Zonas MTMS
Observa cómo cargamos el Shapefile oficial de los 27 barrios de Santiago (LIMITE_BARRIOS.shp), lo proyectamos a EPSG:32719 (metros), reparamos su topología con st_make_valid(), clasificamos los 7 barrios del Gran Matta Sur en sus 4 Zonas y creamos la capa de polígonos zonales mediante st_union():

suppressPackageStartupMessages({
  library(tidyverse)
  library(sf)
  library(arrow)
  library(sfarrow)
  library(mapgl)
  library(plotly)
  library(htmltools)
  library(scales)
  library(DT)
})

options(scipen = 999)

# 1. Carga de Barrios en UTM 19S (EPSG:32719) y clasificación en 4 Zonas MTMS
barrios_stgo_utm &lt;- st_read(
  "G:/Mi unidad/research-projects/A-data-infra-rda/sig-shapes-chile/division-administrativa/LÍMITE_BARRIOS_STGO/LIMITE_BARRIOS.shp",
  quiet = TRUE
) |&gt;
  st_transform(32719) |&gt;
  st_make_valid() |&gt;
  mutate(
    zona_corta = case_when(
      BARRIO %in% c("VIEL", "HUEMUL")           ~ "Zona 1",
      BARRIO %in% c("MATTA SUR", "BOGOTA")      ~ "Zona 2",
      BARRIO %in% c("SANTA ELENA")              ~ "Zona 3",
      BARRIO %in% c("FRANKLIN", "SIERRA BELLA") ~ "Zona 4",
      TRUE ~ NA_character_
    ),
    zona_mtms = case_when(
      BARRIO %in% c("VIEL", "HUEMUL")           ~ "Zona 1 (Viel - Huemul)",
      BARRIO %in% c("MATTA SUR", "BOGOTA")      ~ "Zona 2 (Matta Sur - Bogotá)",
      BARRIO %in% c("SANTA ELENA")              ~ "Zona 3 (Santa Elena)",
      BARRIO %in% c("FRANKLIN", "SIERRA BELLA") ~ "Zona 4 (Franklin - Sierra Bella)",
      TRUE ~ NA_character_
    ),
    es_gran_matta_sur = !is.na(zona_corta)
  )

# 2. Disolución geométrica (st_union) de los 7 barrios en los 4 polígonos de Zona
zonas_mtms_utm &lt;- barrios_stgo_utm |&gt;
  filter(es_gran_matta_sur) |&gt;
  group_by(zona_corta, zona_mtms) |&gt;
  summarise(
    barrios_zona = paste(BARRIO, collapse = " + "),
    geometry     = st_union(geometry),
    .groups      = "drop"
  ) |&gt;
  st_make_valid()

# 3. Versiones en WGS84 (EPSG:4326) listas para MapLibre WebGL
barrios_stgo  &lt;- st_transform(barrios_stgo_utm, 4326)
zonas_mtms_sf &lt;- st_transform(zonas_mtms_utm, 4326)




Paso 2. Geometría Maestra Censal, Densidad (hab/ha) e Interpolación Areal Ponderada
Aquí resolvemos dos problemas clásicos de un proyecto SIG:

Cálculo de la Densidad Residencial (densidad_mzn): En EPSG:32719, st_area(shape) entrega la superficie exacta de cada manzana en metros cuadrados (\(\text{m}^2\)). Dividimos por 10.000 para obtener hectáreas (\(\text{ha}\)) y dividimos n_per / area_hectareas.
Interpolación Areal Ponderada de Veredas (st_intersection): Como los polígonos de veredas del catastro SIEDU 2018 no coinciden exactamente con las manzanas del Censo 2024, intersectamos ambas geometrías y ponderamos la nota de cada fragmento (1 = Excelente a 5 = No existe) por su superficie intersectada:

\[\text{qswalk\_pond}_i = \frac{\sum_j \text{qswalk}_{ij} \cdot \text{Área}_{ij}}{\sum_j \text{Área}_{ij}}, \qquad \text{Deterioro Veredas (\%)} = \left(\frac{\text{qswalk\_pond}_i - 1}{4}\right) \times 100\]

# 1. Censo 2024 a nivel de manzana (Comuna de Santiago CUT == 13101)
censo_stgo_utm &lt;- read_parquet(
  "G:/Mi unidad/research-projects/A-data-infra-rda/censo-chile/censo-2024/geodatos-2024/Cartografia_censo2024_Pais_Manzanas.parquet"
) |&gt;
  rename_with(tolower) |&gt;
  filter(cut == 13101) |&gt;
  mutate(cod_mzn = as.character(manzent)) |&gt;
  select(
    cod_mzn, cut, comuna, n_per, n_hog, n_vp,
    n_ocupado, n_desocupado, n_fuera_fuerza_trabajo,
    prom_escolaridad18, n_analfabet,
    n_deficit_cuantitativo, n_viv_hacinadas, n_hog_allegados, n_tenencia_arrendada_sin_contrato,
    n_cise_rec_independientes, n_cise_rec_trabajador_no_remunerado,
    n_inmigrantes, n_pueblos_orig, n_afrodescendencia,
    n_edad_0_5, n_edad_6_13, n_edad_60_mas, prom_edad,
    shape
  ) |&gt;
  st_as_sf(crs = 4326) |&gt;
  st_transform(32719) |&gt;
  st_make_valid() |&gt;
  mutate(
    area_m2        = as.numeric(sf::st_area(shape)),
    area_hectareas = area_m2 / 10000,
    densidad_mzn   = if_else(area_hectareas &gt; 0, n_per / area_hectareas, NA_real_)
  )

# 2. Interpolación areal ponderada de calidad de veredas SIEDU sobre manzanas Censo 2024
gdb_siedu_path &lt;- "G:/Mi unidad/research-projects/A-data-infra-rda/sig-shapes-chile/siedu-chile/Cartografia_SIEDU_1ra_medicion/20211028_CARTOGRAFIA_SIEDU_LB2018.gdb"

swalk_stgo_utm &lt;- st_read(
  gdb_siedu_path,
  query = "SELECT * FROM LB2018_IS40_Calidad_Veredas WHERE CUT = 13101",
  quiet = TRUE
) |&gt;
  mutate(
    qswalk = case_when(
      VEREDAS == "EXCELENTE" ~ 1,
      VEREDAS == "BUENO"     ~ 2,
      VEREDAS == "REGULAR"   ~ 3,
      VEREDAS == "MALO"      ~ 4,
      VEREDAS == "NO EXISTE" ~ 5,
      TRUE ~ NA_real_
    )
  ) |&gt;
  drop_na(qswalk) |&gt;
  st_make_valid() |&gt;
  st_transform(32719)

veredas_mzn_ponderada &lt;- suppressWarnings(
  st_intersection(
    swalk_stgo_utm |&gt; select(qswalk),
    censo_stgo_utm |&gt; select(cod_mzn)
  )
) |&gt;
  mutate(area_fragmento = as.numeric(st_area(Shape))) |&gt;
  st_drop_geometry() |&gt;
  group_by(cod_mzn) |&gt;
  summarise(
    qswalk_pond = sum(qswalk * area_fragmento, na.rm = TRUE) / sum(area_fragmento, na.rm = TRUE),
    .groups = "drop"
  )




Paso 3. Cruce por Punto Interior, Imputación Espacial y Promedios sobre Manzanas Habitadas
Observa cómo resolvemos el cruce entre manzanas, barrios y la Matriz de Bienestar Humano Territorial (CIT), y cómo aplicamos la función imputar_vecino_cercano() basada en sf::st_nearest_feature():

# 1. Cruce espacial garantizado mediante punto en superficie (st_point_on_surface)
centroides_mzn &lt;- st_point_on_surface(censo_stgo_utm |&gt; select(cod_mzn))

join_barrios &lt;- st_join(
  centroides_mzn,
  barrios_stgo_utm |&gt; select(barrio = BARRIO, zona_corta, zona_mtms, es_gran_matta_sur),
  join = st_intersects
)

# Rescate por vecino más cercano para manzanas cuyo borde cae sobre una avenida limítrofe
if (any(is.na(join_barrios$barrio))) {
  idx_na &lt;- which(is.na(join_barrios$barrio))
  near_b &lt;- st_nearest_feature(centroides_mzn[idx_na, ], barrios_stgo_utm)
  join_barrios$barrio[idx_na]            &lt;- barrios_stgo_utm$BARRIO[near_b]
  join_barrios$zona_corta[idx_na]        &lt;- barrios_stgo_utm$zona_corta[near_b]
  join_barrios$zona_mtms[idx_na]         &lt;- barrios_stgo_utm$zona_mtms[near_b]
  join_barrios$es_gran_matta_sur[idx_na] &lt;- barrios_stgo_utm$es_gran_matta_sur[near_b]
}

# 2. Construcción de indicadores e imputación por vecino más cercano
imputar_vecino_cercano &lt;- function(sf_obj, vars_imputar, puntos_utm) {
  df_out &lt;- sf_obj
  for (v in vars_imputar) {
    na_mask &lt;- is.na(df_out[[v]])
    if (any(na_mask) && any(!na_mask)) {
      idx_near &lt;- st_nearest_feature(puntos_utm[na_mask, ], puntos_utm[!na_mask, ])
      df_out[[v]][na_mask] &lt;- df_out[[v]][!na_mask][idx_near]
    }
  }
  return(df_out)
}

mzn_stgo_sf &lt;- censo_stgo_utm |&gt;
  st_transform(4326) |&gt;
  left_join(st_drop_geometry(join_barrios), by = "cod_mzn") |&gt;
  left_join(veredas_mzn_ponderada, by = "cod_mzn") |&gt;
  mutate(
    manzana_habitada      = n_per &gt; 0,
    prom_escolaridad18    = if_else(n_per &gt; 0 & prom_escolaridad18 &gt; 0, prom_escolaridad18, NA_real_),
    pct_analfabetismo     = if_else(n_per &gt; 0, (n_analfabet / n_per) * 100, NA_real_),
    pct_deficit_cuant     = if_else(n_vp &gt; 0, (n_deficit_cuantitativo / n_vp) * 100, NA_real_),
    ind_deterioro_veredas = ((qswalk_pond - 1) / 4) * 100
  ) |&gt;
  imputar_vecino_cercano(
    c("prom_escolaridad18", "pct_analfabetismo", "pct_deficit_cuant", "qswalk_pond", "ind_deterioro_veredas"),
    centroides_mzn
  ) |&gt;
  mutate(
    cat_veredas = case_when(
      qswalk_pond &lt; 1.5 ~ "Excelente",
      qswalk_pond &lt; 2.5 ~ "Buena",
      qswalk_pond &lt; 3.5 ~ "Regular",
      qswalk_pond &lt; 4.5 ~ "Mala",
      TRUE              ~ "Inexistente"
    )
  )

# 3. Resumen por Barrio y por Zona (promediando variables censales SOLO en manzanas habitadas)
resumen_barrios &lt;- mzn_stgo_sf |&gt;
  st_drop_geometry() |&gt;
  group_by(barrio, zona_corta, zona_mtms, es_gran_matta_sur) |&gt;
  summarise(
    n_manzanas            = n(),
    n_manzanas_hab        = sum(manzana_habitada, na.rm = TRUE),
    poblacion_total       = sum(n_per, na.rm = TRUE),
    densidad_media        = mean(densidad_mzn[manzana_habitada], na.rm = TRUE),
    prom_escolaridad18    = mean(prom_escolaridad18[manzana_habitada], na.rm = TRUE),
    pct_deficit_cuant     = mean(pct_deficit_cuant[n_vp &gt; 0], na.rm = TRUE),
    ind_deterioro_veredas = mean(ind_deterioro_veredas, na.rm = TRUE),
    qswalk_pond           = mean(qswalk_pond, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(
    cat_veredas = case_when(
      qswalk_pond &lt; 1.5 ~ "Excelente",
      qswalk_pond &lt; 2.5 ~ "Buena",
      qswalk_pond &lt; 3.5 ~ "Regular",
      qswalk_pond &lt; 4.5 ~ "Mala",
      TRUE              ~ "Inexistente"
    )
  )

resumen_zonas &lt;- mzn_stgo_sf |&gt;
  st_drop_geometry() |&gt;
  filter(es_gran_matta_sur) |&gt;
  group_by(zona_corta, zona_mtms) |&gt;
  summarise(
    barrios_incluidos     = paste(sort(unique(barrio)), collapse = " + "),
    ind_deterioro_veredas = mean(ind_deterioro_veredas, na.rm = TRUE),
    .groups = "drop"
  )




Paso 4. Construcción del Geovisor WebGL (mapgl) y Gráfico Comparado (plotly) en Vivo
Para demostrar el resultado sin sobrecargar el peso de esta guía docente, filtramos a continuación las 431 manzanas de los 7 barrios del Gran Matta Sur y ejecutamos la arquitectura real de capas jerárquicas de mapgl::maplibre() junto con el gráfico comparado de los 27 barrios en plotly:

Demostración en Vivo: Mapa WebGL con Tooltip HTMLDemostración en Vivo: Gráfico Barrial con Líneas de Zona (plotly)



fmt_num &lt;- function(x, digits = 1) {
  format(round(x, digits), big.mark = ".", decimal.mark = ",", nsmall = digits, trim = TRUE)
}

prom_stgo_veredas &lt;- mean(mzn_stgo_sf$ind_deterioro_veredas, na.rm = TRUE)

# Filtramos las 431 manzanas del Gran Matta Sur para la demostración interactiva ligera
mzn_gms_demo &lt;- mzn_stgo_sf |&gt;
  filter(es_gran_matta_sur) |&gt;
  left_join(
    resumen_barrios |&gt; select(barrio, barrio_veredas = ind_deterioro_veredas),
    by = "barrio"
  ) |&gt;
  mutate(
    diff_barrio   = ind_deterioro_veredas - barrio_veredas,
    signo_barrio  = if_else(diff_barrio &gt;= 0, paste0("+", fmt_num(diff_barrio, 1)), fmt_num(diff_barrio, 1)),
    diff_stgo     = ind_deterioro_veredas - prom_stgo_veredas,
    signo_stgo    = if_else(diff_stgo &gt;= 0, paste0("+", fmt_num(diff_stgo, 1)), fmt_num(diff_stgo, 1)),
    barrio_titulo = str_to_title(barrio),
    tooltip_html  = paste0(
      "&lt;div style='font-family: system-ui, sans-serif; font-size: 12px; line-height: 1.42; padding: 6px 8px; min-width: 245px; color: #1f2937;'&gt;",
      "&lt;div style='font-size: 13px; font-weight: 700; color: #111827; margin-bottom: 2px;'&gt;Barrio: ", barrio, "&lt;/div&gt;",
      "&lt;div style='font-size: 11px; color: #4b5563; margin-bottom: 6px;'&gt;",
      "Manzana: &lt;strong&gt;", cod_mzn, "&lt;/strong&gt;&lt;br&gt;",
      "Población: &lt;strong&gt;", fmt_num(n_per, 0), " hab.&lt;/strong&gt; | Viviendas: &lt;strong&gt;", fmt_num(n_vp, 0), "&lt;/strong&gt; | Hogares: &lt;strong&gt;", fmt_num(n_hog, 0), "&lt;/strong&gt;&lt;br&gt;",
      "Densidad Residencial: &lt;strong&gt;", fmt_num(densidad_mzn, 1), " hab/ha&lt;/strong&gt;",
      "&lt;/div&gt;",
      "&lt;div style='background: #f8fafc; border-left: 3px solid #ea580c; padding: 5px 7px; margin-bottom: 6px; border-radius: 3px;'&gt;",
      "&lt;span style='font-size: 11px; color: #374151;'&gt;Deterioro de Veredas (SIEDU):&lt;/span&gt;&lt;br&gt;",
      "&lt;strong style='font-size: 15px; color: #111827;'&gt;", fmt_num(ind_deterioro_veredas, 1), "%&lt;/strong&gt;&lt;br&gt;",
      "&lt;span style='font-size: 11px; color: #4b5563;'&gt;Promedio Barrio (", barrio_titulo, "): &lt;strong&gt;", fmt_num(barrio_veredas, 1), "%&lt;/strong&gt; (", signo_barrio, " pp)&lt;/span&gt;&lt;br&gt;",
      "&lt;span style='font-size: 11px; color: #4b5563;'&gt;Promedio Santiago: &lt;strong&gt;", fmt_num(prom_stgo_veredas, 1), "%&lt;/strong&gt; (", signo_stgo, " pp)&lt;/span&gt;",
      "&lt;/div&gt;",
      "&lt;div style='font-size: 11px; color: #444;'&gt;• Estado Predominante de Vereda: &lt;strong&gt;", cat_veredas, " (nota ", fmt_num(qswalk_pond, 1), " de 5)&lt;/strong&gt;&lt;/div&gt;",
      "&lt;/div&gt;"
    )
  ) |&gt;
  select(cod_mzn, ind_deterioro_veredas, tooltip_html, shape)

cortes_demo &lt;- c(0, 50, 100)
paleta_demo &lt;- c("#ffffcc", "#fd8d3c", "#800026")

mapa_demo &lt;- maplibre(bounds = zonas_mtms_sf, style = carto_style("positron")) |&gt;
  add_fill_layer(
    id                 = "mzn_fill_layer",
    source             = mzn_gms_demo,
    fill_color         = interpolate(column = "ind_deterioro_veredas", values = cortes_demo, stops = paleta_demo),
    fill_opacity       = 0.84,
    fill_outline_color = "rgba(255, 255, 255, 0.30)",
    tooltip            = "tooltip_html",
    hover_options      = list(fill_opacity = 0.98, fill_outline_color = "#111111")
  ) |&gt;
  add_line_layer(
    id = "zonas_halo", source = zonas_mtms_sf,
    line_color = "#ffffff", line_width = 3.2, line_opacity = 0.8
  ) |&gt;
  add_line_layer(
    id = "zonas_highlight", source = zonas_mtms_sf,
    line_color = "#ea580c", line_width = 2.2, line_opacity = 0.95
  ) |&gt;
  add_symbol_layer(
    id = "zonas_labels", source = zonas_mtms_sf,
    text_field = c("get", "zona_corta"), text_size = 12,
    text_color = "#9a3412", text_halo_color = "#ffffff", text_halo_width = 1.8
  ) |&gt;
  add_legend(
    legend_title = "Deterioro Veredas (%)",
    type = "continuous", values = cortes_demo, colors = paleta_demo,
    layer_id = "mzn_fill_layer", position = "bottom-right", interactive = TRUE
  ) |&gt;
  add_navigation_control(position = "top-right") |&gt;
  add_fullscreen_control(position = "top-right")

browsable(div(style = "width: 100%; height: 64vh; border: 1px solid #ddd; border-radius: 6px;", mapa_demo))










df_barrios_demo &lt;- resumen_barrios |&gt;
  mutate(
    sector_destacado = if_else(
      es_gran_matta_sur,
      "Gran Matta Sur (Sector Suroriente - 7 barrios)",
      "Resto de Barrios de Santiago (20 barrios)"
    ),
    etiqueta_barrio = if_else(es_gran_matta_sur, paste0(barrio, " (", str_replace(zona_corta, "Zona ", "Z"), ")"), barrio),
    barrio_ordenado = fct_reorder(etiqueta_barrio, ind_deterioro_veredas),
    texto_hover = paste0(
      "&lt;b&gt;Barrio: ", barrio, "&lt;/b&gt;&lt;br&gt;",
      "Deterioro de Veredas: &lt;b&gt;", fmt_num(ind_deterioro_veredas, 1), "%&lt;/b&gt;&lt;br&gt;",
      "Estado Predominante: ", cat_veredas, " (nota ", fmt_num(qswalk_pond, 1), " de 5)"
    )
  )

p_demo &lt;- ggplot(df_barrios_demo, aes(x = barrio_ordenado, y = ind_deterioro_veredas)) +
  geom_col(aes(fill = sector_destacado, text = texto_hover), width = 0.74) +
  geom_hline(yintercept = mean(df_barrios_demo$ind_deterioro_veredas), linetype = "dashed", color = "#111827", linewidth = 0.7) +
  coord_flip() +
  scale_fill_manual(
    values = c(
      "Gran Matta Sur (Sector Suroriente - 7 barrios)" = "#f77f00",
      "Resto de Barrios de Santiago (20 barrios)"      = "#457b9d"
    ),
    name = ""
  ) +
  scale_y_continuous(labels = function(x) paste0(x, "%")) +
  labs(
    title = "Infraestructura: Deterioro de Veredas por Barrio (SIEDU, %)",
    x = NULL, y = "Deterioro de Veredas (%)"
  ) +
  theme_minimal(base_size = 11)

ggplotly(p_demo, tooltip = "text", height = 560) |&gt;
  layout(legend = list(orientation = "h", x = 0, y = -0.12)) |&gt;
  config(displaylogo = FALSE)

3.1. Disolución de Barrios en las 4 Zonas MTMS (st_union)
La Mesa Territorial Matta Sur (MTMS) y el CEIDELC organizan los 7 barrios del Sector Suroriente en 4 Zonas. En lugar de editar un Shapefile manualmente en QGIS, lo generamos de forma 100% reproducible en R:
barrios_stgo_utm &lt;- st_read(".../LIMITE_BARRIOS.shp", quiet = TRUE) |&gt;
  st_transform(32719) |&gt;
  st_make_valid() |&gt;
  mutate(
    zona_corta = case_when(
      BARRIO %in% c("VIEL", "HUEMUL")           ~ "Zona 1",
      BARRIO %in% c("MATTA SUR", "BOGOTA")      ~ "Zona 2",
      BARRIO %in% c("SANTA ELENA")              ~ "Zona 3",
      BARRIO %in% c("FRANKLIN", "SIERRA BELLA") ~ "Zona 4",
      TRUE ~ NA_character_
    ),
    es_gran_matta_sur = !is.na(zona_corta)
  )

# Fusión geométrica de los 7 barrios en los 4 polígonos zonales
zonas_mtms_utm &lt;- barrios_stgo_utm |&gt;
  filter(es_gran_matta_sur) |&gt;
  group_by(zona_corta, zona_mtms) |&gt;
  summarise(
    barrios_zona = paste(BARRIO, collapse = " + "),
    geometry     = st_union(geometry),
    .groups      = "drop"
  ) |&gt;
  st_make_valid()

3.2. Interpolación Areal de Veredas SIEDU sobre Manzanas 2024
¿Cómo transferimos el estado de veredas (LB2018_IS40_Calidad_Veredas, medido en 2018) a las manzanas del Censo 2024 cuando sus geometrías difieren? “Las manzanas censales mandan”:
# 1. Intersección geométrica en metros (EPSG:32719)
veredas_interseccion &lt;- suppressWarnings(
  st_intersection(
    swalk_stgo_utm |&gt; select(qswalk),   # Puntaje 1 (Excelente) a 5 (No existe)
    censo_stgo_utm |&gt; select(cod_mzn)   # Geometría maestra Censo 2024
  )
) |&gt;
  mutate(area_fragmento = as.numeric(st_area(Shape))) |&gt;
  st_drop_geometry()

# 2. Promedio ponderado por área dentro de cada manzana censal y re-escalamiento 0-100%
veredas_mzn_ponderada &lt;- veredas_interseccion |&gt;
  group_by(cod_mzn) |&gt;
  summarise(
    qswalk_pond = sum(qswalk * area_fragmento, na.rm = TRUE) / sum(area_fragmento, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(ind_deterioro_veredas = ((qswalk_pond - 1) / 4) * 100)

3.3. Función Constructora de Mapas (crear_mapa_manzana_stgo)
En vez de copiar y pegar 8 veces el código de maplibre(), encapsulamos el diseño en una función reutilizable con soporte para unidades (% o años), rangos fijos o por cuantiles, y tooltip estandarizado:
crear_mapa_manzana_stgo &lt;- function(
    datos_sf, barrios_sf, zonas_sf, var_col, var_barrio_col, prom_santiago_val,
    titulo_leyenda, subtitulo_var, paleta_colores,
    sufijo_unidad = "%", sufijo_brecha = " pp", rango_fijo = NULL, lineas_extra_fn = NULL
) {
  # 1. Cortes de leyenda (fijos ej. 0-100% en Seguridad, o percentiles P2-P50-P98)
